// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { RdfExplorer, clearMetadataCache } from "../../../main/frontend/graph-explorer/rdf-explorer.ts";
import {
  chooseLabel,
  parseLanguagePreferences,
  RDFS_LABEL,
  labelQuery,
  neighborsQuery,
} from "../../../main/frontend/graph-explorer/rdf-vocabulary.ts";
const iri = (value) => ({ type: "uri", value }),
  literal = (value, language) => ({
    type: "literal",
    value,
    ...(language ? { "xml:lang": language } : {}),
  });
test('one failed metadata batch does not discard successful labels or cache failures as missing', async () => {
  let fail = true;
  const ids = Array.from({length: 90}, (_, i) => `urn:partial-label:${i}`);
  const resolver = new RdfExplorer('urn:endpoint:partial-labels', ['en'], async query => {
    const requested = ids.filter(id => query.includes(`<${id}>`));
    if (fail && requested.includes(ids[0])) throw new Error('endpoint rejected one batch');
    return {results:{bindings:requested.map(id=>({resource:iri(id),label:literal(`Name ${id.split(':').at(-1)}`,'en'),labelProperty:iri(RDFS_LABEL)}))}};
  });
  try {
    await resolver.resolve(ids);
    assert.equal(resolver.label(ids[89]),'Name 89');
    assert.notEqual(resolver.label(ids[0]),'Name 0');
    fail = false;
    await resolver.resolve(ids);
    assert.equal(resolver.label(ids[0]),'Name 0');
  } finally {resolver.dispose();}
});
test("preferred languages outrank vocabulary; regional, untagged and any-language fallbacks are deterministic", () => {
  const candidates = [
    { value: "Name", language: "en", property: RDFS_LABEL },
    { value: "Navn", language: "nb", property: "urn:custom:displayName" },
    { value: "Generic", language: "", property: RDFS_LABEL },
  ];
  assert.equal(chooseLabel(candidates, ["nb", "en"]), "Navn");
  assert.equal(chooseLabel(candidates, ["en-gb", "nb"]), "Name");
  assert.equal(chooseLabel(candidates, ["de"]), "Generic");
  assert.deepEqual(parseLanguagePreferences("NB, en, nb"), ["nb", "en"]);
  assert.throws(() =>
    parseLanguagePreferences(Array.from({ length: 17 }, (_, i) => "en-x" + i)),
  );
  assert.throws(() =>
    parseLanguagePreferences('en\" } SERVICE <https://evil>'),
  );
});
test("a generic predicate label resolves identically in the loaded graph and action menu; endpoints remain isolated", async () => {
  clearMetadataCache();
  let calls = 0;
  const query = async () => {
    calls++;
    return {
      results: {
        bindings: [
          {
            resource: iri("urn:relation"),
            labelProperty: iri(RDFS_LABEL),
            label: literal("forfatter", "nb"),
          },
          {
            resource: iri("urn:relation"),
            labelProperty: iri(RDFS_LABEL),
            label: literal("author", "en"),
          },
        ],
      },
    };
  };
  const resolver = new RdfExplorer("urn:endpoint:a", ["nb", "en"], query);
  const graph = {
    revision: 1,
    nodes: [
      { id: "urn:s", kind: "iri", label: "urn:s" },
      { id: "urn:o", kind: "iri", label: "urn:o" },
    ],
    edges: [
      {
        id: "edge",
        source: "urn:s",
        target: "urn:o",
        predicate: "urn:relation",
        label: "ex:relation",
      },
    ],
  };
  resolver.observe(graph);
  await Promise.all([
    resolver.resolve(["urn:relation"]),
    resolver.resolve(["urn:relation"]),
  ]);
  assert.equal(calls, 1);
  assert.equal(resolver.apply(graph).edges[0].label, "forfatter");
  assert.equal(resolver.label("urn:relation"), "forfatter");
  await resolver.resolve(["urn:relation"]);
  assert.equal(calls, 1);
  const other = new RdfExplorer("urn:endpoint:b", ["nb", "en"], query);
  assert.notEqual(other.label("urn:relation"), "forfatter");
  resolver.dispose();
  other.dispose();
});
test("loaded custom label predicates work with language-tagged literals without another request", () => {
  const resolver = new RdfExplorer("urn:custom", ["fr", "en"], async () => ({
    results: { bindings: [] },
  }));
  const graph = {
    revision: 0,
    nodes: [
      { id: "urn:x", label: "urn:x", kind: "iri" },
      {
        id: "literal",
        label: "Monsieur",
        termValue: "Monsieur",
        language: "fr",
        kind: "literal",
      },
    ],
    edges: [
      {
        id: "e",
        source: "urn:x",
        target: "literal",
        predicate: "urn:our:displayName",
        label: "displayName",
      },
    ],
  };
  resolver.observe(graph);
  assert.equal(resolver.apply(graph).nodes[0].label, "Monsieur");
  resolver.dispose();
});
test("label lookups use bounded VALUES and SKOS-XL; neighbor limits stay per anchor after batching", () => {
  const q = labelQuery(["urn:a", "urn:b"], [], "all", true);
  assert.match(q, /VALUES \?__anchor/);
  assert.match(q, /BIND\(\?__anchor AS \?resource\)/);
  assert.match(q, /literalForm/);
  assert.match(q, /GRAPH \?__graph/);
  const expansion = neighborsQuery(
    ["urn:a", "urn:b"],
    "urn:p",
    "outgoing",
    12,
    "default",
    true,
  );
  assert.equal(expansion.match(/LIMIT 12/g).length, 2);
  assert.doesNotMatch(expansion, /OPTIONAL|SERVICE/);
  assert.throws(() => labelQuery(["urn:a> bad"], [], "default"));
});
test("new schema discoveries invalidate negative label lookups", async () => {
  let schema = false;
  const engine = new RdfExplorer(
    "https://schema-discovery.example/sparql",
    ["en"],
    async (query) => {
      if (query.includes("SELECT DISTINCT ?property")) {
        schema = true;
        return {
          results: {
            bindings: [
              { property: { type: "uri", value: "urn:ex:captionCode" } },
            ],
          },
        };
      }
      return {
        results: {
          bindings:
            schema && query.includes("<urn:ex:captionCode>")
              ? [
                  {
                    resource: { type: "uri", value: "urn:ex:p" },
                    label: {
                      type: "literal",
                      value: "Schema caption",
                      "xml:lang": "en",
                    },
                    labelProperty: { type: "uri", value: "urn:ex:captionCode" },
                  },
                ]
              : [],
        },
      };
    },
  );
  await engine.resolve(["urn:ex:p"]);
  assert.notEqual(engine.label("urn:ex:p"), "Schema caption");
  await engine.discoverVocabulary(["urn:ex:captionCode"]);
  await engine.resolve(["urn:ex:p"]);
  assert.equal(engine.label("urn:ex:p"), "Schema caption");
  engine.dispose();
});
test("loaded SHACL names label their predicate paths and SKOS-XL resolves label nodes", () => {
  const engine = new RdfExplorer("urn:shapes", ["nb", "en"], async () => ({
    results: { bindings: [] },
  }));
  const n = (id, kind = "iri", label = id, language) => ({
    id,
    kind,
    label,
    termValue: label,
    language,
  });
  const graph = {
    revision: 0,
    nodes: [
      n("urn:p"),
      n("urn:shape", "blank"),
      n("urn:label", "literal", "Arbeidsgiver", "nb"),
      n("urn:entity"),
      n("urn:xl", "blank"),
      n("urn:text", "literal", "Person", "nb"),
    ],
    edges: [
      {
        id: "1",
        source: "urn:shape",
        predicate: "http://www.w3.org/ns/shacl#path",
        target: "urn:p",
        label: "path",
      },
      {
        id: "2",
        source: "urn:shape",
        predicate: "http://www.w3.org/ns/shacl#name",
        target: "urn:label",
        label: "name",
      },
      {
        id: "3",
        source: "urn:entity",
        predicate: "http://www.w3.org/2008/05/skos-xl#prefLabel",
        target: "urn:xl",
        label: "prefLabel",
      },
      {
        id: "4",
        source: "urn:xl",
        predicate: "http://www.w3.org/2008/05/skos-xl#literalForm",
        target: "urn:text",
        label: "literalForm",
      },
    ],
  };
  engine.observe(graph);
  assert.equal(engine.label("urn:p"), "Arbeidsgiver");
  assert.equal(engine.label("urn:entity"), "Person");
  engine.dispose();
});

test("custom label policies do not share a negative cache with the default policy", async () => {
  clearMetadataCache();
  let calls = 0;
  const query = async (q) => {
    calls++;
    return {
      results: {
        bindings: q.includes("<urn:captionCode>")
          ? [
              {
                resource: iri("urn:resource"),
                labelProperty: iri("urn:captionCode"),
                label: literal("Custom caption", "en"),
              },
            ]
          : [],
      },
    };
  };
  const first = new RdfExplorer("urn:policy-cache", ["en"], query);
  await first.resolve(["urn:resource"]);
  first.dispose();
  const custom = new RdfExplorer(
    "urn:policy-cache",
    ["en"],
    query,
    "default",
    false,
    false,
    "public",
    ["urn:captionCode"],
  );
  await custom.resolve(["urn:resource"]);
  assert.equal(custom.label("urn:resource"), "Custom caption");
  assert.equal(calls, 2);
  custom.dispose();
  const again = new RdfExplorer(
    "urn:policy-cache",
    ["en"],
    query,
    "default",
    false,
    false,
    "public",
    ["urn:captionCode"],
  );
  await again.resolve(["urn:resource"]);
  assert.equal(calls, 2);
  again.dispose();
});

test("unlabelled IRIs read as words: camelCase properties in lower case, PascalCase names and acronyms kept", async () => {
  const { humanizeIri } = await import("../../../main/frontend/graph-explorer/rdf-vocabulary.ts");
  assert.equal(humanizeIri("http://schema.org/birthDate"), "birth date");
  assert.equal(humanizeIri("http://schema.org/worksFor"), "works for");
  assert.equal(humanizeIri("http://example.org/homePageURL"), "home page URL");
  assert.equal(humanizeIri("http://example.org/NewYork"), "New York");
  assert.equal(humanizeIri("http://example.org/has_part-of"), "has part of");
});
